def get_user_extra_data_by_client_id(
    self, client_id: str, username: str
) -> Dict[str, Any]:
    extra_data = {}
    current_client = self.clients.get(client_id, None)
    user_attributes = self._get_user(username).attributes

    # Always include custom attributes (prefixed with 'custom:')
    for attribute in user_attributes:
        if attribute["Name"].startswith("custom:"):
            extra_data.update({attribute["Name"]: attribute["Value"]})

    # Include other attributes based on ReadAttributes
    if current_client:
        for readable_field in current_client.get_readable_fields():
            # Skip custom attributes as they're already included
            if readable_field.startswith("custom:"):
                continue

            attribute = list(
                filter(
                    lambda f: f["Name"] == readable_field,
                    user_attributes,
                )
            )
            if len(attribute) > 0:
                extra_data.update({attribute[0]["Name"]: attribute[0]["Value"]})
    return extra_data
